// Parse and validate the sentiment analysis output with deterministic fallbacks.
const envelope = $('When Called by Another Workflow').first().json;
const raw = ($input.first().json.output || '').trim();

const ALLOWED_SENTIMENTS = ['positive','neutral','negative','angry','frustrated','urgent'];
const ALLOWED_PRIORITIES = ['low','normal','high','critical'];

function extractJson(text) {
  if (!text) return null;
  const cleaned = text.replace(/```json/gi, '').replace(/```/g, '').trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) return null;
  try { return JSON.parse(cleaned.slice(start, end + 1)); } catch (e) { return null; }
}

const parsed = extractJson(raw);
const fallback = { sentiment: 'neutral', priority: 'normal', urgency: 0, explanation: '' };

let sentiment = parsed && typeof parsed.sentiment === 'string' ? parsed.sentiment.trim().toLowerCase() : fallback.sentiment;
if (!ALLOWED_SENTIMENTS.includes(sentiment)) sentiment = fallback.sentiment;

let priority = parsed && typeof parsed.priority === 'string' ? parsed.priority.trim().toLowerCase() : fallback.priority;
if (!ALLOWED_PRIORITIES.includes(priority)) priority = fallback.priority;

let urgency = parsed && Number(parsed.urgency);
if (!Number.isFinite(urgency)) urgency = fallback.urgency;
urgency = Math.max(0, Math.min(1, urgency));

const explanation = parsed && typeof parsed.explanation === 'string' ? parsed.explanation.slice(0, 200) : fallback.explanation;

const sentimentAnalysis = { sentiment, priority, urgency, explanation, raw };
return [{ json: { ...envelope, sentiment: sentimentAnalysis } }];
